import{_ as l,C as n,o as r,c as i,j as t,a,E as d,a6 as c}from"./chunks/framework.CD0vXS2f.js";const A=JSON.parse('{"title":"05 · OpenTelemetry gen_ai.* Tracing & A1–A12 Readiness Standard","description":"End-to-end OpenTelemetry span correlation across Orchestrator, APIM, Agent Nodes, and MCP Tools—paired with PII-safe DCR redaction and the A1–A12 Agent Readiness Standard.","frontmatter":{"title":"05 · OpenTelemetry gen_ai.* Tracing & A1–A12 Readiness Standard","description":"End-to-end OpenTelemetry span correlation across Orchestrator, APIM, Agent Nodes, and MCP Tools—paired with PII-safe DCR redaction and the A1–A12 Agent Readiness Standard."},"headers":[],"relativePath":"playbooks/agentic-rag-evals/05-otel-tracing-release-gates.md","filePath":"playbooks/agentic-rag-evals/05-otel-tracing-release-gates.md","lastUpdated":1795280666087}'),g={name:"playbooks/agentic-rag-evals/05-otel-tracing-release-gates.md"};function p(y,e,f,u,x,h){const s=n("PlaybookMeta"),o=n("PageBrief");return r(),i("div",null,[e[0]||(e[0]=t("h1",{id:"_05-·-opentelemetry-gen-ai-tracing-a1–a12-readiness-standard",tabindex:"-1"},[a("05 · OpenTelemetry "),t("code",null,"gen_ai.*"),a(" Tracing & "),t("code",null,"A1–A12"),a(" Readiness Standard "),t("a",{class:"header-anchor",href:"#_05-·-opentelemetry-gen-ai-tracing-a1–a12-readiness-standard","aria-label":'Permalink to "05 · OpenTelemetry `gen_ai.*` Tracing & `A1–A12` Readiness Standard"'},"​")],-1)),d(s,{track:"04 · Sandboxed Agentic Harness, Foundry IQ RAG & 7-Layer Evals",verified:"2026-11-19 PST",status:"Live v2.0",printable:""}),d(o,{stage:"govern",readTime:"4 min read",problem:"Multi-agent workflows invoke 3–8 LLM calls and multiple MCP tools per user turn; without W3C traceparent correlation and metadata-only redaction, teams either fly blind or leak sensitive client text into logs.",takeaway:"Propagate W3C traceparent across Orchestrator → Session Container → APIM → Foundry/MCP, emit metadata-only gen_ai.* attributes by default, and require A1–A12 before launch.",csaUse:"Verify the span attribute contract below in Application Insights and attach A1–A12 to your production readiness review."}),e[1]||(e[1]=c('<h2 id="_1-metadata-only-gen-ai-span-contract-m-arch" tabindex="-1">1. Metadata-Only <code>gen_ai.*</code> Span Contract <code>[M]</code> <code>[Arch]</code> <a class="header-anchor" href="#_1-metadata-only-gen-ai-span-contract-m-arch" aria-label="Permalink to &quot;1. Metadata-Only `gen_ai.*` Span Contract `[M]` `[Arch]`&quot;">​</a></h2><p>Keep <code>OTEL_INSTRUMENTATION_GENAI_CAPTURE_MESSAGE_CONTENT=false</code> in production so client documents and PII never enter Log Analytics, while capturing every operational attribute needed for debugging, FinOps, and PTU sizing <span class="ev-badge ev-m">[M]</span> <span class="ev-badge ev-arch">[Arch]</span>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Span Attribute</th><th style="text-align:left;">Source Tier</th><th style="text-align:left;">Operational Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><code>trace_id</code> / <code>parent_span_id</code></td><td style="text-align:left;">W3C <code>traceparent</code> header across all 3 tiers</td><td style="text-align:left;">Reconstructs the full tree of <code>3–8</code> sub-agent/tool calls inside a single user turn.</td></tr><tr><td style="text-align:left;"><code>gen_ai.request.model</code> / <code>gen_ai.response.model</code></td><td style="text-align:left;">Session Container / Foundry SDK <span class="ev-badge ev-m">[M]</span></td><td style="text-align:left;">Detects silent model-snapshot drift across primary, spillover, and DR deployments.</td></tr><tr><td style="text-align:left;"><code>gen_ai.usage.input_tokens</code> / <code>output_tokens</code></td><td style="text-align:left;">Foundry response <code>usage</code> <span class="ev-badge ev-m">[M]</span></td><td style="text-align:left;">Feeds two-regime <code>DeployPeakNormTPM</code> PTU sizing (<a href="/enterprise-azure-ai-hub/playbooks/prompt-caching/govern/13-otel-kql-gate">Playbook 01 · Ch 13</a>).</td></tr><tr><td style="text-align:left;"><code>gen_ai.usage.cached_tokens</code></td><td style="text-align:left;"><code>prompt_tokens_details.cached_tokens</code> / <code>input_tokens_details</code></td><td style="text-align:left;">Verifies <code>≥80%</code> repeat cache hit rate and alerts on prefix-breaking regressions.</td></tr><tr><td style="text-align:left;"><code>agent.node_name</code> / <code>agent.skill_id</code></td><td style="text-align:left;">Agent Harness wrapper</td><td style="text-align:left;">Pinpoints which specific node or skill regressed latency, cache reuse, or tool failure rate.</td></tr><tr><td style="text-align:left;"><code>mcp.tool_name</code> / <code>mcp.citation_count</code></td><td style="text-align:left;">MCP Client wrapper</td><td style="text-align:left;">Tracks Foundry IQ retrieval latency and zero-result knowledge gaps without logging query text.</td></tr></tbody></table><hr><h2 id="_2-the-12-point-enterprise-agentic-readiness-standard-a1–a12-agree" tabindex="-1">2. The 12-Point Enterprise Agentic Readiness Standard (<code>A1–A12</code>) <code>[Agree]</code> <a class="header-anchor" href="#_2-the-12-point-enterprise-agentic-readiness-standard-a1–a12-agree" aria-label="Permalink to &quot;2. The 12-Point Enterprise Agentic Readiness Standard (`A1–A12`) `[Agree]`&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Gate ID</th><th style="text-align:left;">Category</th><th style="text-align:left;">Verification Requirement</th><th style="text-align:left;">Target Pass Bar</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>A1</code></strong></td><td style="text-align:left;">Runtime Isolation</td><td style="text-align:left;">Orchestrator runs <strong>zero</strong> Agent SDK / shell tools; all session execution runs inside microVM-isolated ACA Dynamic Sessions / Sandboxes <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Verified in architecture</td></tr><tr><td style="text-align:left;"><strong><code>A2</code></strong></td><td style="text-align:left;">Immutable Tags</td><td style="text-align:left;">Orchestrator, Frontend, and Session Pool deploy exclusively via <strong>Git commit SHA tags</strong> (never <code>:latest</code>).</td><td style="text-align:left;">Enforced in CI/CD</td></tr><tr><td style="text-align:left;"><strong><code>A3</code></strong></td><td style="text-align:left;">Upload Containment</td><td style="text-align:left;">Uploads enforce extension allowlists, <code>50 MB</code> streaming limits, filename sanitization, and <code>realpath</code> workspace containment.</td><td style="text-align:left;">Security test pass</td></tr><tr><td style="text-align:left;"><strong><code>A4</code></strong></td><td style="text-align:left;">Document Fidelity</td><td style="text-align:left;">Binary PDFs/Office uploads convert via ADLS Gen2 + Azure Content Understanding with explicit error surfacing (<code>503</code>) on pipeline failure <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">E2E upload test pass</td></tr><tr><td style="text-align:left;"><strong><code>A5</code></strong></td><td style="text-align:left;">Grounded RAG &amp; ACLs</td><td style="text-align:left;">Foundry IQ (<code>Azure AI Search</code> MCP) enforces Managed Identity RBAC (<code>Search Index Data Reader</code>) and document-level security trimming <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Cross-tenant negative test</td></tr><tr><td style="text-align:left;"><strong><code>A6</code></strong></td><td style="text-align:left;">Prefix Preservation</td><td style="text-align:left;">Retrieved RAG chunks and per-turn timestamps append strictly at <strong>Position 6</strong> (<code>PCR004</code> clean).</td><td style="text-align:left;"><code>pcr_lint.py</code> exit <code>0</code></td></tr><tr><td style="text-align:left;"><strong><code>A7</code></strong></td><td style="text-align:left;">Streaming Protocol</td><td style="text-align:left;">SSE pipeline streams unbuffered <code>AG-UI</code> events (<code>RUN_STARTED</code> → <code>RUN_FINISHED</code>/<code>RUN_ERROR</code>) with explicit per-turn <code>asyncio.timeout</code>.</td><td style="text-align:left;">Timeout recovery test</td></tr><tr><td style="text-align:left;"><strong><code>A8</code></strong></td><td style="text-align:left;">Skill Trajectory Gate</td><td style="text-align:left;">Modular agent skills pass automated trigger/trajectory checks (<code>waza</code> or pytest golden fixtures).</td><td style="text-align:left;"><code>100%</code> fixture pass</td></tr><tr><td style="text-align:left;"><strong><code>A9</code></strong></td><td style="text-align:left;">Deterministic Contract</td><td style="text-align:left;"><a href="/enterprise-azure-ai-hub/papers/engineering-kits#agent-gate"><code>agent_release_gate.py</code></a> verifies citation ID resolution, allowed tool allowlist, and Pass-2 cache parity (<code>≥1,024</code> cached tokens).</td><td style="text-align:left;">Hard PR merge gate</td></tr><tr><td style="text-align:left;"><strong><code>A10</code></strong></td><td style="text-align:left;">Calibrated Quality</td><td style="text-align:left;">Foundry Evals (<code>Groundedness</code>, <code>Relevance</code>, <code>TaskAdherence</code>) show <code>≤2%</code> delta against baseline snapshot across 50–200 golden cases <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Pre-cutover report</td></tr><tr><td style="text-align:left;"><strong><code>A11</code></strong></td><td style="text-align:left;">Indirect Injection</td><td style="text-align:left;">Multi-turn safety &amp; indirect prompt-injection suite confirms untrusted document content cannot invoke unapproved tools or exfiltrate workspace files <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;"><code>0</code> critical findings</td></tr><tr><td style="text-align:left;"><strong><code>A12</code></strong></td><td style="text-align:left;">Metadata-Only OTel</td><td style="text-align:left;">W3C <code>traceparent</code> correlates all tiers in App Insights with <code>CAPTURE_MESSAGE_CONTENT=false</code> and DCR PII redaction active <span class="ev-badge ev-m">[M]</span>.</td><td style="text-align:left;">Verified in Log Analytics</td></tr></tbody></table>',6))])}const _=l(g,[["render",p]]);export{A as __pageData,_ as default};
